function F({registerIndicator:b,sourceValues:y,nulls:f}){b({id:"oa-kama",name:"Kaufman's Adaptive Moving Average (KAMA)",category:"Trends IIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"},{key:"fastPeriod",type:"number",label:"Fast EMA Period",default:2,min:2,max:5e3,step:1},{key:"slowPeriod",type:"number",label:"Slow EMA Period",default:30,min:2,max:5e3,step:1}],plots:[{key:"kama",type:"line",title:"KAMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(a,r){const o=Math.max(1,Math.floor(Number(r.period)||10)),M=Math.max(2,Math.floor(Number(r.fastPeriod)||2)),A=Math.max(2,Math.floor(Number(r.slowPeriod)||30)),i=y(a,r.source??"close"),d=2/(M+1),s=2/(A+1),c=new Array(a.length).fill(NaN);if(!(d>s))return{kama:f(c)};const l=new Array(a.length).fill(NaN);for(let e=1;e<a.length;e++)Number.isFinite(i[e])&&Number.isFinite(i[e-1])&&(l[e]=Math.abs(i[e]-i[e-1]));const p=new Array(a.length).fill(NaN);let m=0;for(let e=0;e<a.length;e++){Number.isFinite(l[e])&&(m+=l[e]);const t=e-o;t>=0&&Number.isFinite(l[t])&&(m-=l[t]),e>=o&&(p[e]=m)}let n=NaN;for(let e=0;e<a.length;e++){const t=i[e];if(!Number.isFinite(t))continue;let N=0;const h=e>=o&&Number.isFinite(i[e-o])?Math.abs(t-i[e-o]):NaN,u=p[e];Number.isFinite(h)&&Number.isFinite(u)&&u!==0&&(N=h/u);const k=Math.pow(N*(d-s)+s,2);n=Number.isFinite(n)?n+k*(t-n):t,c[e]=n}return{kama:f(c)}}})}export{F as default};
